1	// Shared realtime types + small mapping helpers used across providers.
2	
3	import type { AgentState } from "@/components/ui/orb";
4	import type { AgentState as BarState } from "@/components/ui/bar-visualizer";
5	
6	export type CallState = "idle" | "connecting" | "listening" | "speaking" | "interrupted" | "ended";
7	
8	export interface SessionTurn {
9	  id: string;
10	  who: "agent" | "user";
11	  text: string;
12	  live?: boolean;
13	}
14	
15	// The unified surface every provider exposes to the UI. The UI never talks to a
16	// provider directly — it binds to this, and the active provider is swapped
17	// behind it (mock for the design's fake lifecycle, ElevenLabs for the real one).
18	export interface SessionApi {
19	  callState: CallState;
20	  turns: SessionTurn[];
21	  caption: string;
22	  muted: boolean;
23	  elapsed: number;
24	  isReal: boolean;
25	  toggleMute: () => void;
26	  start: () => void;
27	  hangup: () => void;
28	  interrupt: () => void;
29	  /** End the user's turn now (half-duplex cascade STT). No-op on full-duplex engines. */
30	  sendTurn: () => void;
31	  /** Whether this engine has a manual end-of-turn (only the cascade STT does). */
32	  canSendTurn: boolean;
33	  getInputVolume: () => number;
34	  getOutputVolume: () => number;
35	}
36	
37	export const STATE_LABEL: Record<CallState, string> = {
38	  idle: "IDLE",
39	  connecting: "CONNECTING",
40	  listening: "LISTENING",
41	  speaking: "SPEAKING",
42	  interrupted: "INTERRUPTED",
43	  ended: "ENDED",
44	};
45	
46	export function isLive(s: CallState): boolean {
47	  return s !== "idle" && s !== "ended";
48	}
49	
50	// CallState → ElevenLabs WebGL Orb agentState.
51	export function toOrbState(s: CallState): AgentState {
52	  switch (s) {
53	    case "speaking":
54	      return "talking";
55	    case "listening":
56	    case "interrupted":
57	      return "listening";
58	    case "connecting":
59	      return "thinking";
60	    default:
61	      return null;
62	  }
63	}
64	
65	// CallState → BarVisualizer state.
66	export function toBarState(s: CallState): BarState {
67	  switch (s) {
68	    case "speaking":
69	      return "speaking";
70	    case "connecting":
71	      return "connecting";
72	    case "interrupted":
73	    case "listening":
74	      return "listening";
75	    default:
76	      return "initializing";
77	  }
78	}
