1	"use client";
2	
3	// Real xAI Grok voice engine over a DIRECT browser→xAI WebSocket.
4	//
5	// Architecture (no relay server): mint an ephemeral client-secret at
6	// /api/xai/token, then open `wss://api.x.ai/v1/realtime` carrying the token in
7	// the subprotocol (browsers can't set WS headers). We own the whole audio
8	// pipeline: mic → PCM16 → `input_audio_buffer.append`; inbound
9	// `response.output_audio.delta` → PCM16 → AudioBuffer playback. Barge-in is
10	// server-VAD driven (`input_audio_buffer.speech_started` → stop playback).
11	//
12	// Exposes a surface deliberately parallel to @elevenlabs/react's useConversation
13	// so useRealtimeSession can dispatch to either engine uniformly. Must be called
14	// unconditionally (rules of hooks); it stays inert until start().
15	
16	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
17	import type { Persona } from "@/lib/data";
18	import type { CallState, SessionTurn } from "./types";
19	import { createMicCapture, type MicCapture } from "./mic-capture";
20	import { resolveXaiAgent } from "./xai-agent";
21	import {
22	  base64Pcm16ToFloat32,
23	  calculateRms,
24	  EarlyAudioBuffer,
25	  float32ToPcm16Base64,
26	  PlaybackQueue,
27	} from "./xai-audio";
28	
29	const REALTIME_BASE = "wss://api.x.ai/v1/realtime";
30	const CHUNK_MS = 100;
31	const VOL_GAIN = 3.5;
32	
33	export interface XaiSession {
34	  callState: CallState;
35	  turns: SessionTurn[];
36	  caption: string;
37	  start: () => void;
38	  stop: () => void;
39	  interrupt: () => void;
40	  setMuted: (muted: boolean) => void;
41	  getInputVolume: () => number;
42	  getOutputVolume: () => number;
43	}
44	
45	type XaiEvent = {
46	  type: string;
47	  delta?: string;
48	  transcript?: string;
49	  error?: { type?: string; code?: string; message?: string };
50	  item?: { role?: string; content?: Array<{ type?: string; transcript?: string; text?: string }> };
51	};
52	
53	function extractToken(data: unknown): string | null {
54	  if (typeof data !== "object" || data === null) return null;
55	  const d = data as Record<string, unknown>;
56	  if (typeof d.value === "string") return d.value;
57	  if (typeof d.token === "string") return d.token;
58	  if (typeof d.secret === "string") return d.secret;
59	  const cs = d.client_secret;
60	  if (typeof cs === "string") return cs;
61	  if (cs && typeof cs === "object" && typeof (cs as Record<string, unknown>).value === "string") {
62	    return (cs as Record<string, unknown>).value as string;
63	  }
64	  return null;
65	}
66	
67	export function useXaiSession(active: boolean, persona?: Persona): XaiSession {
68	  const [callState, setCallState] = useState<CallState>("idle");
69	  const [turns, setTurns] = useState<SessionTurn[]>([]);
70	  const [caption, setCaption] = useState("press CALL to begin");
71	
72	  const wsRef = useRef<WebSocket | null>(null);
73	  const ctxRef = useRef<AudioContext | null>(null);
74	  const streamRef = useRef<MediaStream | null>(null);
75	  const captureRef = useRef<MicCapture | null>(null);
76	  const playbackRef = useRef<PlaybackQueue | null>(null);
77	  // Early mic audio captured before the session is configured (parallel init).
78	  const earlyBufRef = useRef<EarlyAudioBuffer | null>(null);
79	  // True once `session.updated` arrives: append chunks stream live; until then
80	  // they accumulate in earlyBufRef.
81	  const streamingRef = useRef(false);
82	
83	  const mutedRef = useRef(false);
84	  const endedRef = useRef(false);
85	  const configuredRef = useRef(false);
86	  const inputRmsRef = useRef(0);
87	  const turnSeqRef = useRef(0);
88	  const agentTurnIdRef = useRef<string | null>(null);
89	  const agentBufRef = useRef("");
90	  const interruptTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
91	  const stateRef = useRef<CallState>("idle");
92	  stateRef.current = callState;
93	  // Latest selected persona, read at start() time (avoids stale closures).
94	  const personaRef = useRef(persona);
95	  personaRef.current = persona;
96	
97	  const teardown = useCallback(() => {
98	    if (interruptTimerRef.current) {
99	      clearTimeout(interruptTimerRef.current);
100	      interruptTimerRef.current = null;
101	    }
102	    if (captureRef.current) {
103	      captureRef.current.stop();
104	      captureRef.current = null;
105	    }
106	    if (streamRef.current) {
107	      streamRef.current.getTracks().forEach((t) => t.stop());
108	      streamRef.current = null;
109	    }
110	    if (playbackRef.current) {
111	      playbackRef.current.stop();
112	      playbackRef.current = null;
113	    }
114	    if (wsRef.current) {
115	      try {
116	        wsRef.current.close();
117	      } catch {
118	        // already closing
119	      }
120	      wsRef.current = null;
121	    }
122	    if (ctxRef.current) {
123	      void ctxRef.current.close();
124	      ctxRef.current = null;
125	    }
126	    configuredRef.current = false;
127	    streamingRef.current = false;
128	    earlyBufRef.current = null;
129	    agentTurnIdRef.current = null;
130	    agentBufRef.current = "";
131	    inputRmsRef.current = 0;
132	  }, []);
133	
134	  const send = useCallback((obj: unknown) => {
135	    const ws = wsRef.current;
136	    if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(obj));
137	  }, []);
138	
139	  const start = useCallback(() => {
140	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
141	    endedRef.current = false;
142	    configuredRef.current = false;
143	    streamingRef.current = false;
144	    setTurns([]);
145	    setCallState("connecting");
146	    setCaption("establishing session…");
147	
148	    const fail = (msg: string) => {
149	      endedRef.current = true;
150	      teardown();
151	      setCallState("ended");
152	      setCaption(msg);
153	    };
154	
155	    // 1) Bring up audio + mic capture IMMEDIATELY, in parallel with the token
156	    //    mint + WS connect (xAI "parallel initialization"). Native AudioContext
157	    //    rate is advertised to xAI so no resampling is needed. Early PCM is
158	    //    buffered (earlyBufRef) until `session.updated`, then flushed — so the
159	    //    first words spoken right after CALL aren't lost.
160	    const ctx = new AudioContext();
161	    ctxRef.current = ctx;
162	    const rate = ctx.sampleRate;
163	    playbackRef.current = new PlaybackQueue(ctx);
164	    earlyBufRef.current = new EarlyAudioBuffer();
165	
166	    // AudioWorklet-based capture: chunking runs on the realtime audio thread;
167	    // the main thread only receives finished CHUNK_MS chunks (mic-capture.ts).
168	    const chunkSize = Math.floor((rate * CHUNK_MS) / 1000);
169	
170	    const startCapture = async () => {
171	      try {
172	        const stream = await navigator.mediaDevices.getUserMedia({
173	          audio: {
174	            channelCount: 1,
175	            echoCancellation: true,
176	            noiseSuppression: true,
177	            autoGainControl: true,
178	          },
179	        });
180	        if (endedRef.current) {
181	          // Hung up (or failed) while the mic prompt was open.
182	          stream.getTracks().forEach((t) => t.stop());
183	          return;
184	        }
185	        streamRef.current = stream;
186	        if (ctx.state === "suspended") await ctx.resume();
187	        const capture = await createMicCapture(ctx, stream, chunkSize, (chunk) => {
188	          inputRmsRef.current = mutedRef.current ? 0 : calculateRms(chunk);
189	          if (mutedRef.current) return;
190	          const audio = float32ToPcm16Base64(chunk);
191	          // Stream live once configured; until then accumulate the early audio.
192	          if (streamingRef.current) send({ type: "input_audio_buffer.append", audio });
193	          else earlyBufRef.current?.push(audio);
194	        });
195	        if (endedRef.current) {
196	          // Hung up while the worklet module loaded.
197	          capture.stop();
198	          return;
199	        }
200	        captureRef.current = capture;
201	      } catch {
202	        fail("— microphone permission denied —");
203	      }
204	    };
205	
206	    // Kick capture off now — do not await it, and do not wait for the WS.
207	    void startCapture();
208	
209	    void (async () => {
210	      // 2) Mint the ephemeral client-secret server-side (in parallel with capture).
211	      let token: string | null = null;
212	      try {
213	        const res = await fetch("/api/xai/token", { method: "POST" });
214	        const data = await res.json();
215	        if (!res.ok) {
216	          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
217	          return;
218	        }
219	        token = extractToken(data);
220	      } catch {
221	        fail("— could not reach token endpoint —");
222	        return;
223	      }
224	      if (!token) {
225	        fail("— no xAI token returned —");
226	        return;
227	      }
228	      if (endedRef.current) return; // hung up (or mic denied) during fetch
229	
230	      // ── transcript helpers ──────────────────────────────────────────────
231	      // The setTurns updaters must stay PURE (no ref mutation inside): React
232	      // StrictMode double-invokes them, so any id/sequence mutation happens here
233	      // once, before calling setTurns.
234	      const pushAgentDelta = (delta: string) => {
235	        agentBufRef.current += delta;
236	        const text = agentBufRef.current;
237	        setCaption(text);
238	        let id = agentTurnIdRef.current;
239	        if (id) {
240	          const tid = id;
241	          setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
242	        } else {
243	          id = `x${turnSeqRef.current++}`;
244	          agentTurnIdRef.current = id;
245	          const tid = id;
246	          setTurns((prev) => [...prev, { id: tid, who: "agent", text, live: true }]);
247	        }
248	      };
249	      const finalizeAgent = () => {
250	        const id = agentTurnIdRef.current;
251	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
252	        agentTurnIdRef.current = null;
253	        agentBufRef.current = "";
254	      };
255	      const pushUser = (text: string) => {
256	        if (!text) return;
257	        const tid = `x${turnSeqRef.current++}`;
258	        setTurns((prev) => [...prev, { id: tid, who: "user", text }]);
259	        setCaption(text);
260	      };
261	
262	      // 3) Resolve the active persona's agent config, then open the WS
263	      //    (token rides the subprotocol since browsers can't set WS headers).
264	      const agent = resolveXaiAgent(personaRef.current?.id);
265	      const ws = new WebSocket(`${REALTIME_BASE}?model=${encodeURIComponent(agent.model)}`, [
266	        `xai-client-secret.${token}`,
267	      ]);
268	      wsRef.current = ws;
269	
270	      const configure = () => {
271	        if (configuredRef.current) return;
272	        configuredRef.current = true;
273	        send({
274	          type: "session.update",
275	          session: {
276	            instructions: agent.instructions,
277	            voice: agent.voice,
278	            audio: {
279	              input: { format: { type: "audio/pcm", rate } },
280	              output: { format: { type: "audio/pcm", rate } },
281	            },
282	            turn_detection: agent.turnDetection,
283	            tools: agent.tools,
284	          },
285	        });
286	      };
287	
288	      ws.onmessage = (event) => {
289	        if (endedRef.current) return; // ignore late events after teardown
290	        let msg: XaiEvent;
291	        try {
292	          msg = JSON.parse(typeof event.data === "string" ? event.data : "") as XaiEvent;
293	        } catch {
294	          return;
295	        }
296	        switch (msg.type) {
297	          case "conversation.created":
298	          case "session.created":
299	            configure();
300	            break;
301	          case "session.updated": {
302	            // Session is configured: switch capture to live streaming and flush
303	            // any audio the user already spoke during connect — in order, BEFORE
304	            // the greeting bootstrap — so their opening words reach the model.
305	            streamingRef.current = true;
306	            const buffered = earlyBufRef.current?.drain() ?? [];
307	            for (const audio of buffered) {
308	              send({ type: "input_audio_buffer.append", audio });
309	            }
310	            setCallState("listening");
311	            setCaption("listening…");
312	            // Prompt an opening line so the agent speaks first.
313	            send({
314	              type: "conversation.item.create",
315	              item: {
316	                type: "message",
317	                role: "user",
318	                content: [{ type: "input_text", text: agent.firstMessage }],
319	              },
320	            });
321	            send({ type: "response.create" });
322	            break;
323	          }
324	          case "response.output_audio.delta":
325	            if (msg.delta) {
326	              playbackRef.current?.enqueue(base64Pcm16ToFloat32(msg.delta));
327	              if (stateRef.current !== "interrupted") setCallState("speaking");
328	            }
329	            break;
330	          case "response.output_audio_transcript.delta":
331	            if (msg.delta) pushAgentDelta(msg.delta);
332	            break;
333	          case "response.done":
334	            finalizeAgent();
335	            if (stateRef.current === "speaking") setCallState("listening");
336	            break;
337	          case "input_audio_buffer.speech_started":
338	            // Server VAD detected the user — barge-in: stop the agent audio.
339	            playbackRef.current?.stop();
340	            finalizeAgent();
341	            setCallState("interrupted");
342	            if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
343	            interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
344	            break;
345	          case "input_audio_buffer.committed":
346	          case "input_audio_buffer.speech_stopped":
347	            if (stateRef.current === "interrupted") setCallState("listening");
348	            break;
349	          case "conversation.item.added":
350	          case "conversation.item.created": {
351	            const item = msg.item;
352	            if (item?.role === "user") {
353	              const t = item.content?.find((c) => c.transcript || c.text);
354	              if (t) pushUser((t.transcript ?? t.text ?? "").trim());
355	            }
356	            break;
357	          }
358	          case "error":
359	            // Surface but don't kill — a fatal error will also close the socket.
360	            setCaption(`— ${msg.error?.message ?? "xAI error"} —`);
361	            break;
362	          default:
363	            break;
364	        }
365	      };
366	
367	      ws.onerror = () => {
368	        if (endedRef.current) return;
369	        endedRef.current = true;
370	        teardown();
371	        setCallState("ended");
372	        setCaption("— connection error —");
373	      };
374	
375	      ws.onclose = () => {
376	        if (endedRef.current) return;
377	        endedRef.current = true;
378	        teardown();
379	        setCallState("ended");
380	        setCaption("— call ended —");
381	      };
382	    })();
383	  }, [send, teardown]);
384	
385	  const stop = useCallback(() => {
386	    endedRef.current = true;
387	    teardown();
388	    setCallState("ended");
389	    setCaption("— call ended —");
390	  }, [teardown]);
391	
392	  const interrupt = useCallback(() => {
393	    if (stateRef.current !== "speaking") return;
394	    playbackRef.current?.stop();
395	    setCallState("interrupted");
396	    if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
397	    interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
398	  }, []);
399	
400	  const setMuted = useCallback((muted: boolean) => {
401	    mutedRef.current = muted;
402	    if (muted) inputRmsRef.current = 0;
403	  }, []);
404	
405	  const getInputVolume = useCallback(() => Math.min(1, inputRmsRef.current * VOL_GAIN), []);
406	  const getOutputVolume = useCallback(
407	    () => Math.min(1, (playbackRef.current?.level ?? 0) * VOL_GAIN),
408	    [],
409	  );
410	
411	  // Hang up + reset if the provider is switched away from xAI mid-session.
412	  useEffect(() => {
413	    if (active) return;
414	    if (stateRef.current !== "idle") {
415	      endedRef.current = true;
416	      teardown();
417	      setCallState("idle");
418	      setTurns([]);
419	      setCaption("press CALL to begin");
420	    }
421	  }, [active, teardown]);
422	
423	  // Cleanup on unmount.
424	  useEffect(() => () => teardown(), [teardown]);
425	
426	  return useMemo<XaiSession>(
427	    () => ({
428	      callState,
429	      turns,
430	      caption,
431	      start,
432	      stop,
433	      interrupt,
434	      setMuted,
435	      getInputVolume,
436	      getOutputVolume,
437	    }),
438	    [callState, turns, caption, start, stop, interrupt, setMuted, getInputVolume, getOutputVolume],
439	  );
440	}
