1	"use client";
2	
3	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
4	import { useConversation } from "@elevenlabs/react";
5	import { TRANSCRIPT_SCRIPT, type Persona, type Provider } from "@/lib/data";
6	import type { CallState, SessionApi, SessionTurn } from "./types";
7	import { useXaiSession } from "./use-xai-session";
8	import { useOpenaiSession } from "./use-openai-session";
9	import { useCascadeSession } from "./use-cascade-session";
10	import { useFalSession } from "./use-fal-session";
11	import { useMoshiSession } from "./use-moshi-session";
12	
13	const SCRIPT_TURNS: SessionTurn[] = TRANSCRIPT_SCRIPT.map((t, i) => ({
14	  id: `s${i}`,
15	  who: t.who,
16	  text: t.text,
17	}));
18	
19	const LAST = TRANSCRIPT_SCRIPT.length - 1;
20	
21	function mockCaption(state: CallState): string {
22	  switch (state) {
23	    case "idle":
24	      return "press CALL to begin";
25	    case "ended":
26	      return "— call ended —";
27	    case "connecting":
28	      return "establishing session…";
29	    case "listening":
30	      return TRANSCRIPT_SCRIPT[LAST - 1].text;
31	    case "speaking":
32	      return TRANSCRIPT_SCRIPT[LAST].text;
33	    case "interrupted":
34	      return "… you interrupted";
35	  }
36	}
37	
38	/**
39	 * Unified realtime session. `provider.engine` selects the engine:
40	 *   - undefined → the design's mock lifecycle (timers + TRANSCRIPT_SCRIPT)
41	 *   - "elevenlabs" → real conversation via `@elevenlabs/react`
42	 *   - "xai" → real Grok voice via a direct WebSocket (useXaiSession)
43	 *   - "openai" → real gpt-realtime-2 voice via WebRTC (useOpenaiSession)
44	 *   - "fal" → full-duplex PersonaPlex via a direct WebSocket (useFalSession)
45	 *   - "moshi" → full-duplex PersonaPlex on the LOCAL MLX server (useMoshiSession)
46	 * All expose the same `SessionApi` so the UI is provider-agnostic.
47	 *
48	 * `useXaiSession` and `useOpenaiSession` share one interface, so the dispatcher
49	 * picks whichever is active as `custom` and routes every control through it.
50	 *
51	 * All real-engine hooks (`useConversation`, `useXaiSession`, `useOpenaiSession`)
52	 * are called unconditionally (rules of hooks) and stay inert until their engine
53	 * is selected and started.
54	 */
55	export function useRealtimeSession({
56	  provider,
57	  persona,
58	  lmModelId,
59	  voiceBargeIn,
60	}: {
61	  provider: Provider;
62	  persona?: Persona;
63	  /** Cascade-only: overrides the catalog default LM model (from the Providers picker). */
64	  lmModelId?: string;
65	  /** OpenAI-only: let user speech interrupt the agent (settings INTERRUPTIONS toggle). */
66	  voiceBargeIn?: boolean;
67	}): SessionApi {
68	  const engine = provider.engine;
69	  const isReal = !!engine;
70	
71	  const [callState, setCallState] = useState<CallState>(isReal ? "idle" : "listening");
72	  const [turns, setTurns] = useState<SessionTurn[]>(isReal ? [] : SCRIPT_TURNS);
73	  const [caption, setCaption] = useState<string>(
74	    isReal ? "press CALL to begin" : mockCaption("listening"),
75	  );
76	  const [muted, setMuted] = useState(false);
77	  const [elapsed, setElapsed] = useState(0);
78	
79	  const stateRef = useRef(callState);
80	  stateRef.current = callState;
81	  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
82	  const clearTimers = () => {
83	    timers.current.forEach(clearTimeout);
84	    timers.current = [];
85	  };
86	
87	  // ── ElevenLabs real conversation ──────────────────────────────────────────
88	  const realPhase = useRef<"idle" | "active" | "ended">("idle");
89	  const conversation = useConversation({
90	    micMuted: muted,
91	    onMessage: (msg: { source?: string; message?: string }) => {
92	      const who = msg.source === "user" ? "user" : "agent";
93	      const text = msg.message ?? "";
94	      if (!text) return;
95	      setTurns((prev) => [...prev, { id: `r${prev.length}`, who, text }]);
96	      setCaption(text);
97	    },
98	    onError: () => {
99	      realPhase.current = "ended";
100	      setCallState("ended");
101	      setCaption("— connection error —");
102	    },
103	  });
104	
105	  const { status, mode, isSpeaking, startSession, endSession } = conversation;
106	
107	  // ── Custom real engines (own WebSocket / WebRTC, shared interface) ─────────
108	  const xai = useXaiSession(engine === "xai", persona);
109	  const openai = useOpenaiSession(engine === "openai", persona, voiceBargeIn ?? false);
110	  const cascade = useCascadeSession(engine === "cascade", persona, lmModelId);
111	  const fal = useFalSession(engine === "fal", persona);
112	  const moshi = useMoshiSession(engine === "moshi", persona);
113	  // Whichever custom engine is active owns the session; null ⇒ ElevenLabs/mock.
114	  const custom =
115	    engine === "xai"
116	      ? xai
117	      : engine === "openai"
118	        ? openai
119	        : engine === "cascade"
120	          ? cascade
121	          : engine === "fal"
122	            ? fal
123	            : engine === "moshi"
124	              ? moshi
125	              : null;
126	
127	  // The active call state comes from whichever engine owns the session.
128	  const activeCallState: CallState = custom ? custom.callState : callState;
129	
130	  // Derive real CallState from the conversation status/mode (ElevenLabs only).
131	  useEffect(() => {
132	    if (engine !== "elevenlabs" || realPhase.current === "idle") return;
133	    if (realPhase.current === "ended") {
134	      setCallState("ended");
135	      return;
136	    }
137	    if (status === "connecting") setCallState("connecting");
138	    else if (status === "error") setCallState("ended");
139	    else if (status === "disconnected") setCallState("ended");
140	    else if (status === "connected") {
141	      setCallState(mode === "speaking" || isSpeaking ? "speaking" : "listening");
142	      setCaption((c) => (c === "establishing session…" ? "listening…" : c));
143	    }
144	  }, [engine, status, mode, isSpeaking]);
145	
146	  // ── Mock lifecycle ──────────────────────────────────────────────────────────
147	  // First-load drift: listening → speaking after 5s (matches the prototype).
148	  useEffect(() => {
149	    if (isReal) return;
150	    if (callState !== "listening") return;
151	    const t = setTimeout(() => setCallState("speaking"), 5000);
152	    return () => clearTimeout(t);
153	    // eslint-disable-next-line react-hooks/exhaustive-deps
154	  }, [isReal]);
155	
156	  // Caption sync for the mock engine.
157	  useEffect(() => {
158	    if (isReal) return;
159	    setCaption(mockCaption(callState));
160	  }, [isReal, callState]);
161	
162	  // Elapsed ticker (all engines) — keyed off whichever engine owns the call.
163	  useEffect(() => {
