178	    // eslint-disable-next-line react-hooks/exhaustive-deps
179	  }, [muted, engine, status]);
180	
181	  // Reset to the active engine's initial state when the engine changes. End any
182	  // live ElevenLabs session we're navigating away from (xAI tears itself down
183	  // via its own `active` effect).
184	  useEffect(() => {
185	    clearTimers();
186	    try {
187	      if (realPhase.current === "active") endSession();
188	    } catch {
189	      // no active ElevenLabs session
190	    }
191	    realPhase.current = "idle";
192	    if (isReal) {
193	      setCallState("idle");
194	      setTurns([]);
195	      setCaption("press CALL to begin");
196	    } else {
197	      setCallState("listening");
