235	      setCallState("connecting");
236	      timers.current.push(setTimeout(() => setCallState("listening"), 1400));
237	      timers.current.push(setTimeout(() => setCallState("speaking"), 3600));
238	    } else {
239	      setCallState("ended");
240	    }
241	  }, [engine, custom, callState, startSession, endSession]);
242	
