1	// Framework-free Web Audio helpers for the xAI Grok voice engine.
2	//
3	// xAI's realtime API exchanges raw PCM16 little-endian audio as base64 strings
4	// over the WebSocket (no codec). We capture mic Float32 frames, convert to
5	// PCM16, and base64-encode for `input_audio_buffer.append`; inbound
6	// `response.output_audio.delta` chunks are the reverse. Sample rate is the
7	// browser's native AudioContext rate end-to-end — we advertise it to xAI in
8	// `session.update`, so no resampling is needed (mirrors the xai-cookbook).
9	
10	/** Float32 [-1,1] → PCM16 little-endian bytes. */
11	export function float32ToPcm16Bytes(float32: Float32Array): Uint8Array {
12	  const pcm16 = new Int16Array(float32.length);
13	  for (let i = 0; i < float32.length; i++) {
14	    const s = Math.max(-1, Math.min(1, float32[i]));
15	    pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
16	  }
17	  return new Uint8Array(pcm16.buffer);
18	}
19	
20	/** PCM16 little-endian bytes → Float32 [-1,1]. */
21	export function pcm16BytesToFloat32(bytes: Uint8Array): Float32Array {
22	  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
23	  const n = Math.floor(bytes.byteLength / 2);
24	  const float32 = new Float32Array(n);
25	  for (let i = 0; i < n; i++) {
26	    const s = view.getInt16(i * 2, true);
27	    float32[i] = s / (s < 0 ? 0x8000 : 0x7fff);
28	  }
29	  return float32;
30	}
31	
32	/** Float32 [-1,1] → PCM16 → base64. */
33	export function float32ToPcm16Base64(float32: Float32Array): string {
34	  return arrayBufferToBase64(float32ToPcm16Bytes(float32).buffer as ArrayBuffer);
35	}
36	
37	/** base64 PCM16 → Float32 [-1,1]. */
38	export function base64Pcm16ToFloat32(base64: string): Float32Array {
39	  const binary = atob(base64);
40	  const bytes = new Uint8Array(binary.length);
41	  for (let i = 0; i < binary.length; i++) {
42	    bytes[i] = binary.charCodeAt(i);
43	  }
44	  const pcm16 = new Int16Array(bytes.buffer);
45	  const float32 = new Float32Array(pcm16.length);
46	  for (let i = 0; i < pcm16.length; i++) {
47	    float32[i] = pcm16[i] / (pcm16[i] < 0 ? 0x8000 : 0x7fff);
48	  }
49	  return float32;
50	}
51	
52	function arrayBufferToBase64(buffer: ArrayBuffer): string {
53	  const bytes = new Uint8Array(buffer);
54	  let binary = "";
55	  // Chunk to stay well under the argument-count limit of String.fromCharCode.
56	  const CHUNK = 0x8000;
57	  for (let i = 0; i < bytes.byteLength; i += CHUNK) {
58	    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
59	  }
60	  return btoa(binary);
61	}
62	
63	/**
64	 * Bounded FIFO of base64 PCM16 `input_audio_buffer.append` chunks captured
65	 * BEFORE the xAI session is configured.
66	 *
67	 * xAI's "parallel initialization" guidance: open the mic immediately (in
68	 * parallel with the token mint + WS connect), buffer the user's early speech
69	 * client-side, then flush it the instant `session.updated` arrives — so the
70	 * first words spoken right after pressing CALL aren't lost. Capacity-bounded so
71	 * a stalled or failed configuration can't grow memory without limit (the oldest
72	 * chunk is dropped past `maxChunks`).
73	 */
74	export class EarlyAudioBuffer {
75	  private chunks: string[] = [];
76	  private readonly maxChunks: number;
77	
78	  /** @param maxChunks default 50 ≈ 5 s at 100 ms/chunk. */
79	  constructor(maxChunks = 50) {
80	    this.maxChunks = maxChunks;
81	  }
82	
83	  push(base64: string): void {
84	    this.chunks.push(base64);
85	    if (this.chunks.length > this.maxChunks) this.chunks.shift();
86	  }
87	
88	  /** Return everything buffered (in order) and reset — flush on session ready. */
89	  drain(): string[] {
90	    const out = this.chunks;
91	    this.chunks = [];
92	    return out;
93	  }
94	
95	  clear(): void {
96	    this.chunks = [];
97	  }
98	
99	  get size(): number {
100	    return this.chunks.length;
101	  }
102	}
103	
104	/** Root-mean-square level of a frame, ~0..1. */
105	export function calculateRms(float32: Float32Array): number {
106	  let sum = 0;
107	  for (let i = 0; i < float32.length; i++) sum += float32[i] * float32[i];
108	  return Math.sqrt(sum / float32.length);
109	}
110	
111	/**
112	 * Gap-less playback of streamed PCM16 chunks via chained AudioBufferSourceNodes.
113	 * `stop()` clears the queue + kills the current source for barge-in. `level`
114	 * exposes the currently-playing chunk's RMS so the orb can react to TTS output.
115	 */
116	export class PlaybackQueue {
117	  private ctx: AudioContext;
118	  private queue: Float32Array[] = [];
119	  private playing = false;
120	  private current: AudioBufferSourceNode | null = null;
121	  private _level = 0;
122	
123	  constructor(ctx: AudioContext) {
124	    this.ctx = ctx;
125	  }
126	
127	  enqueue(chunk: Float32Array): void {
128	    this.queue.push(chunk);
129	    if (!this.playing) {
130	      this.playing = true;
131	      this.playNext();
132	    }
133	  }
134	
135	  private playNext(): void {
136	    const chunk = this.queue.shift();
137	    if (!chunk) {
138	      this.playing = false;
139	      this.current = null;
140	      this._level = 0;
141	      return;
142	    }
143	    const buffer = this.ctx.createBuffer(1, chunk.length, this.ctx.sampleRate);
144	    buffer.getChannelData(0).set(chunk);
145	    const source = this.ctx.createBufferSource();
146	    source.buffer = buffer;
147	    source.connect(this.ctx.destination);
148	    this.current = source;
149	    this._level = calculateRms(chunk);
150	    source.onended = () => {
151	      if (this.current === source) this.current = null;
152	      this.playNext();
153	    };
154	    source.start();
155	  }
156	
157	  /** Barge-in: stop now and drop anything queued. */
158	  stop(): void {
159	    if (this.current) {
160	      try {
161	        this.current.stop();
162	        this.current.disconnect();
163	      } catch {
164	        // already stopped
165	      }
166	      this.current = null;
167	    }
168	    this.queue = [];
169	    this.playing = false;
170	    this._level = 0;
171	  }
172	
173	  get level(): number {
174	    return this._level;
175	  }
176	
177	  get isPlaying(): boolean {
178	    return this.playing;
179	  }
180	}
