// Mints a short-lived Gemini Live ephemeral auth token server-side so the
// browser can open a WebSocket to Google WITHOUT ever seeing GEMINI_API_KEY.
//
// Flow: client POSTs here → we call the v1alpha auth-token service via
// @google/genai → return { token }. The browser then connects with
//   wss://…/v1alpha.GenerativeService.BidiGenerateContentConstrained?access_token=<token>
//
// Unlike the xAI/OpenAI mint routes (plain fetch), Google documents no raw REST
// endpoint for token creation — only the SDK — so this route uses @google/genai.
// The token is UNCONSTRAINED (no liveConnectConstraints): persona config stays
// client-side in lib/realtime/gemini-agent.ts, mirroring the xAI engine.
//
// Dev only: GEMINI_API_KEY is provided via fnox (`fnox exec -- bun run dev`).

import { GoogleGenAI } from "@google/genai";

export const runtime = "nodejs";
// Never cache a freshly-minted token.
export const dynamic = "force-dynamic";

// Single-use token: one CALL press = one mint = one Live session.
const TOKEN_TTL_MINUTES = 30;
const NEW_SESSION_WINDOW_MINUTES = 1;

export async function POST(): Promise<Response> {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    // Do not echo any key material; just say it's unset.
    return Response.json(
      { error: "GEMINI_API_KEY is not set on the server (provide it via fnox)." },
      { status: 500 },
    );
  }

  // Ephemeral tokens are v1alpha-only (SDK: "Support in v1alpha only").
  const ai = new GoogleGenAI({ apiKey, httpOptions: { apiVersion: "v1alpha" } });
  const now = Date.now();

  try {
    const token = await ai.authTokens.create({
      config: {
        uses: 1,
        expireTime: new Date(now + TOKEN_TTL_MINUTES * 60_000).toISOString(),
        newSessionExpireTime: new Date(now + NEW_SESSION_WINDOW_MINUTES * 60_000).toISOString(),
      },
    });
    if (!token.name) {
      return Response.json({ error: "Gemini returned a token without a name." }, { status: 502 });
    }
    return Response.json(
      { token: token.name },
      { headers: { "Cache-Control": "no-store" } },
    );
  } catch (err) {
    return Response.json(
      {
        error: `Gemini auth-token mint failed: ${err instanceof Error ? err.message : "unknown error"}`,
      },
      { status: 502 },
    );
  }
}

// Gemini Live agent configuration — the source of truth for what each persona
// sounds and behaves like on the real Gemini Live voice engine.
//
// Same shape and philosophy as xai-agent.ts: shared transport settings in BASE,
// per-persona overrides for voice + prompt + greeting, merged by
// `resolveGeminiAgent(personaId)`. Prompts are the condensed Furutsubaki
// manifestations (docs/persona-architecture.md); the OpenAI module remains the
// reference implementation.
//
// Voice casting is an INITIAL read from the prebuilt-voice tone table
// (listen in AI Studio) — audition and recast freely, the descriptions are
// coarse: Sulafat "warm F", Achernar "soft F", Algenib "gravelly M",
// Charon "informative M", Laomedeia "upbeat F", Algieba "smooth M",
// Despina "smooth F".

// Prebuilt Gemini Live voices (native-audio roster); `(string & {})` keeps
// autocomplete while admitting new voice names without a type change.
export type GeminiVoice =
  | "Puck"
  | "Charon"
  | "Kore"
  | "Fenrir"
  | "Aoede"
  | "Leda"
  | "Orus"
  | "Zephyr"
  | "Achernar"
  | "Achird"
  | "Algenib"
  | "Algieba"
  | "Alnilam"
  | "Autonoe"
  | "Callirrhoe"
  | "Despina"
  | "Enceladus"
  | "Erinome"
  | "Gacrux"
  | "Iapetus"
  | "Laomedeia"
  | "Pulcherrima"
  | "Rasalgethi"
  | "Sadachbia"
  | "Sadaltager"
  | "Schedar"
  | "Sulafat"
  | "Umbriel"
  | "Vindemiatrix"
  | "Zubenelgenubi"
  | (string & {});

/** Gemini's VAD knobs (`realtimeInputConfig.automaticActivityDetection`). Unlike
 * xAI's numeric threshold, start/end sensitivity are coarse two-level enums. */
export interface GeminiActivityDetection {
  startOfSpeechSensitivity: "START_SENSITIVITY_LOW" | "START_SENSITIVITY_HIGH";
  endOfSpeechSensitivity: "END_SENSITIVITY_LOW" | "END_SENSITIVITY_HIGH";
  /** Audio kept before detected speech start, so first words aren't clipped. */
  prefixPaddingMs: number;
  /** How long the user must stay silent before the server ends their turn. */
  silenceDurationMs: number;
}

export interface GeminiAgentConfig {
  /** Live model for the setup message (`models/<model>`). */
  model: string;
  /** A prebuilt Gemini voice name. */
  voice: GeminiVoice;
  /** System prompt sent in `setup.systemInstruction`. */
  instructions: string;
  /** Prompt that elicits the agent's opening line (sent as realtimeInput text). */
  firstMessage: string;
  /** Turn-taking tuning, passed through to `automaticActivityDetection`. */
  activityDetection: GeminiActivityDetection;
}

// VAD presets matched to persona pacing, translated from the xAI numeric
// presets: a HIGH start sensitivity hears soft openings (xAI threshold ≤0.6),
// LOW demands clearer speech (xAI 0.85); a HIGH end sensitivity ends turns
// quickly (snappy personas), LOW tolerates thinking pauses.
const VAD_SNAPPY: GeminiActivityDetection = {
  startOfSpeechSensitivity: "START_SENSITIVITY_LOW",
  endOfSpeechSensitivity: "END_SENSITIVITY_HIGH",
  prefixPaddingMs: 300,
  silenceDurationMs: 480,
};
const VAD_RELAXED: GeminiActivityDetection = {
  startOfSpeechSensitivity: "START_SENSITIVITY_HIGH",
  endOfSpeechSensitivity: "END_SENSITIVITY_LOW",
  prefixPaddingMs: 400,
  silenceDurationMs: 900,
};
const VAD_PATIENT: GeminiActivityDetection = {
  startOfSpeechSensitivity: "START_SENSITIVITY_HIGH",
  endOfSpeechSensitivity: "END_SENSITIVITY_LOW",
  prefixPaddingMs: 500,
  silenceDurationMs: 1200,
};

