// Headless probe of the Gemini Live WS protocol, mirroring use-gemini-session:
// mint token via the dev server route → open the v1alpha Constrained WS →
// send the Aria persona setup → await setupComplete → elicit the greeting via
// realtimeInput.text → report audio bytes + transcript. No mic involved.

const res = await fetch("http://localhost:3000/api/gemini/token", { method: "POST" });
const { token, error } = (await res.json()) as { token?: string; error?: string };
if (!token) throw new Error(`token mint failed: ${error}`);
console.log("token minted:", token.slice(0, 24) + "…");

const URL_WS =
  "wss://generativelanguage.googleapis.com/ws/google.ai.generativelanguage.v1alpha.GenerativeService.BidiGenerateContentConstrained";

const ws = new WebSocket(`${URL_WS}?access_token=REDACTED;

let audioBytes = 0;
let transcript = "";
let turnComplete = false;

const done = new Promise<void>((resolve, reject) => {
  const timeout = setTimeout(() => reject(new Error("timeout after 30s")), 30_000);

  ws.onopen = () => {
    console.log("ws open — sending setup");
    ws.send(
      JSON.stringify({
        setup: {
          model: "models/gemini-3.1-flash-live-preview",
          generationConfig: {
            responseModalities: ["AUDIO"],
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: "Sulafat" } } },
          },
          systemInstruction: {
            parts: [{ text: "You are Aria, a warm calm guide. Keep replies to one sentence." }],
          },
          realtimeInputConfig: {
            automaticActivityDetection: {
              startOfSpeechSensitivity: "START_SENSITIVITY_HIGH",
              endOfSpeechSensitivity: "END_SENSITIVITY_LOW",
              prefixPaddingMs: 400,
              silenceDurationMs: 900,
            },
          },
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          tools: [{ googleSearch: {} }],
        },
      }),
    );
  };

  ws.onmessage = async (event) => {
    const raw =
      typeof event.data === "string"
        ? event.data
        : event.data instanceof Blob
          ? await event.data.text()
          : new TextDecoder().decode(event.data as ArrayBuffer);
    const msg = JSON.parse(raw);
    if (msg.setupComplete) {
      console.log("setupComplete — eliciting greeting via realtimeInput.text");
      ws.send(
        JSON.stringify({
          realtimeInput: { text: "Welcome me warmly in one short sentence as Aria." },
        }),
      );
      return;
    }
    const c = msg.serverContent;
    if (!c) {
      console.log("other message:", raw.slice(0, 200));
      return;
    }
    for (const part of c.modelTurn?.parts ?? []) {
      if (part.inlineData?.data) audioBytes += part.inlineData.data.length;
    }
    if (c.outputTranscription?.text) transcript += c.outputTranscription.text;
    if (c.interrupted) console.log("interrupted");
    if (c.turnComplete) {
      turnComplete = true;
      clearTimeout(timeout);
      resolve();
    }
  };

  ws.onerror = () => reject(new Error("ws error"));
  ws.onclose = (e) => {
    if (!turnComplete) reject(new Error(`ws closed early: code=${e.code} reason=${e.reason}`));
  };
});

await done;
ws.close();
console.log("── RESULT ──");
console.log("audio base64 chars:", audioBytes, `(≈${Math.round((audioBytes * 0.75) / 48000)}s @24kHz PCM16)`);
console.log("greeting transcript:", transcript.trim());

